 | shrine rank = None
 | annual festival = Ken-sho: January 3 ({{ill|Ganshiki-sai|ja|元始祭|12=draft|12=draft}}) ・ October 17 ({{ill|Kannamesai|ja|神嘗祭|12=draft|12=draft}})<br/>Kōrei-den: January 7 ({{ill|Senteisai|ja|先帝祭|12=draft|12=draft}}) ・ {{ill|Vernal Equinox Day|ja|春分日|12=draft|12=draft}} ({{ill|Spring Imperial Festival|ja|春季皇霊祭|1=Kōreisai|lt=Spring Kōreisai|12=draft|12=draft}}) ・ April 3 ({{ill|Jimmu Tennō-sai|ja|神武天皇祭|12=draft|12=draft}}) ・ {{ill|Autumnal Equinox Day|ja|秋分日|12=draft|12=draft}} (Autumn Imperial Festival)<br/>Shin-den: Vernal Equinox Day (Spring Shrine Festival) ・ Autumnal Equinox Day (Autumn Shrine Festival)<br/>Shinka-den: November 23 ({{ill|Niinamesai|ja|新嘗祭|12=draft|12=draft}})
