 | enshrined deities = Ken-sho: {{ill|Amaterasu Ōmikami|ja|天照大御神|1=Amaterasu|lt=Amaterasu Ōmikami|qq=draft|qq=draft|12=simple|13=User:Immanuelle/Amaterasu Ōmikami|13=User:Immanuelle/Amaterasu|qq=|ja_comment=jawiki redirects to 天照大神}}<br/>Kōrei-den: [[:en:List of emperors of Japan|Emperors]]・{{ill|Imperial Family|ja|皇族|qq=draft|qq=draft|12=simple|13=User:Immanuelle/Imperial Family|qq=}} spirits<br/>Shin-den: {{ill|Tenshin Chigi|ja|天神地祇|qq=draft|qq=draft|12=simple|13=User:Immanuelle/Tenshin Chigi|qq=|ja_comment=jawiki redirects to 天津神・国津神}}
 | shrine Rank = None
